CustomField.formula:
IF(
	AND(
		TEXT(Order.Order_Type__c) != 'Opportunity',
		TEXT(Order.Order_Type__c) != ''
	),
	if (Exchange_Rates_Related__c != null,
		((Exchange_Rates_Related__r.ConversionRate__c * Total_Data_Cost_In_USD__c) / VAT__c / Usage_Actual__c) / 100 * Usage_Actual__c,
		Usage_Actual__c * UnitPrice
	),
	IF(
		Usage_Actual__c < Quantity,
		Usage_Actual__c,
		Quantity
	) * UnitPrice
)
